export function validatePublicStationWrite(data, { streamUpdate = false } = {}) {
  const fields = streamUpdate ? streamUpdateFields : publicStationFields;
  if (!data || typeof data !== 'object' || Array.isArray(data) ||
      Object.keys(data).some(key => !fields.has(key))) {
    throw new Error('Invalid public station payload.');
  }
  return data;
}
